// Dump returns diagnostic information about the connection pool.
// It provides visibility into pool state including addresses, connection counts,
// and health status for troubleshooting and monitoring.
func (p *connPool) Dump() []PoolStats {
	var stats []PoolStats

	p.conns.Range(func(key, value interface{}) bool {
		addr := key.(string)
		trans := value.(*transports)

		stat := PoolStats{
			Address:   addr,
			ConnCount: int(trans.size),
			IsHealthy: true, // Connections in pool are assumed healthy
		}

		// Attempt to get active stream count if transport exposes it
		// This is a best-effort operation using atomic load for thread safety
		currentIndex := atomic.LoadUint32(&trans.index)
		if currentIndex < trans.size {
			stat.ActiveStreams = int(currentIndex)
		}

		stats = append(stats, stat)
		return true
	})

	return stats
}

