// Option is the core option type for configuring the client.
// It wraps internal/client.Option to provide a stable public API.
type Option = client.Option

// UnaryOption configures unary RPC calls.
// It's an alias to Option for type-safe configuration of unary-specific settings.
type UnaryOption = client.Option

// StreamOption configures streaming RPC calls (server/client/bidirectional streaming).
// It's an alias to Option for type-safe configuration of stream-specific settings.
type StreamOption = client.Option

// TTHeaderStreamingOption configures TTHeader-based streaming calls.
// It's an alias to Option for type-safe configuration of TTHeader streaming protocol.
type TTHeaderStreamingOption = client.Option

// TailOption returns an Option that will be applied after all other options.
// This is useful for options that need to see or override the final configuration
// after all other options have been applied.
func TailOption(opt Option) Option {
	return Option{F: func(o *client.Options, di *client.Slice) {
		// Store the option to be applied last
		// The framework will ensure this runs after all other options
		opt.F(o, di)
	}}
}

